import { eq } from 'drizzle-orm';
import type { drizzle } from 'drizzle-orm/node-sqlite';
import {
  GuidanceOriginSchema,
  GuidanceSyncStatusSchema,
} from '../../types/guidance-source';
import type { GuidanceUpdate } from '../../types/guidance';
import { guidanceSources } from './schema';

export class GuidanceSources {
  constructor(private readonly db: ReturnType<typeof drizzle>) {}

  private metadata(id: string) {
    const row = this.db
      .select()
      .from(guidanceSources)
      .where(eq(guidanceSources.id, id))
      .get();
    return row
      ? {
          origin: GuidanceOriginSchema.parse(row.origin),
          sync: GuidanceSyncStatusSchema.parse(row.sync),
        }
      : {};
  }

  set({
    id,
    origin,
    sync,
  }: Pick<GuidanceUpdate, 'origin' | 'sync'> & { id: string }): void {
    if (origin === undefined && sync === undefined) return;
    if (origin === null) {
      this.db.delete(guidanceSources).where(eq(guidanceSources.id, id)).run();
      return;
    }
    const prior = this.metadata(id);
    const values = {
      id,
      origin: GuidanceOriginSchema.parse(origin ?? prior.origin),
      sync: GuidanceSyncStatusSchema.parse(sync ?? prior.sync),
    };
    this.db
      .insert(guidanceSources)
      .values(values)
      .onConflictDoUpdate({
        target: guidanceSources.id,
        set: { origin: values.origin, sync: values.sync },
      })
      .run();
  }
}
